/* Insert missing catalog rows only. Existing values are not overwritten. */
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM sec.AppRole WHERE RoleCode='FINANCE') INSERT sec.AppRole(RoleCode,RoleName) VALUES('FINANCE',N'Finance');
IF NOT EXISTS(SELECT 1 FROM sec.AppRole WHERE RoleCode='LOGISTICS') INSERT sec.AppRole(RoleCode,RoleName) VALUES('LOGISTICS',N'Logistics');
IF NOT EXISTS(SELECT 1 FROM sec.AppRole WHERE RoleCode='SYSTEM_ADMIN') INSERT sec.AppRole(RoleCode,RoleName) VALUES('SYSTEM_ADMIN',N'Quản trị kỹ thuật');
IF NOT EXISTS(SELECT 1 FROM cfg.Site WHERE SiteCode=N'1000') INSERT cfg.Site(SiteCode,SiteName) VALUES(N'1000',N'Site 1000');
IF NOT EXISTS(SELECT 1 FROM cfg.Site WHERE SiteCode=N'6000') INSERT cfg.Site(SiteCode,SiteName) VALUES(N'6000',N'Site 6000');
IF NOT EXISTS(SELECT 1 FROM cfg.DataScope WHERE ScopeCode='FINANCE_SHARED') INSERT cfg.DataScope(ScopeCode,ScopeName) VALUES('FINANCE_SHARED',N'FINANCE_SHARED');
IF NOT EXISTS(SELECT 1 FROM cfg.ScopeSite WHERE ScopeCode='FINANCE_SHARED' AND SiteCode=N'1000') INSERT cfg.ScopeSite VALUES('FINANCE_SHARED',N'1000');
IF NOT EXISTS(SELECT 1 FROM cfg.ScopeSite WHERE ScopeCode='FINANCE_SHARED' AND SiteCode=N'6000') INSERT cfg.ScopeSite VALUES('FINANCE_SHARED',N'6000');
IF NOT EXISTS(SELECT 1 FROM cfg.DataScope WHERE ScopeCode='SITE_1000') INSERT cfg.DataScope(ScopeCode,ScopeName) VALUES('SITE_1000',N'SITE_1000');
IF NOT EXISTS(SELECT 1 FROM cfg.ScopeSite WHERE ScopeCode='SITE_1000' AND SiteCode=N'1000') INSERT cfg.ScopeSite VALUES('SITE_1000',N'1000');
IF NOT EXISTS(SELECT 1 FROM cfg.DataScope WHERE ScopeCode='SITE_6000') INSERT cfg.DataScope(ScopeCode,ScopeName) VALUES('SITE_6000',N'SITE_6000');
IF NOT EXISTS(SELECT 1 FROM cfg.ScopeSite WHERE ScopeCode='SITE_6000' AND SiteCode=N'6000') INSERT cfg.ScopeSite VALUES('SITE_6000',N'6000');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='PO_UPDATED' AND OwnerRoleCode<>'FINANCE') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='PO_UPDATED') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('PO_UPDATED',N'PO_UPDATED','FINANCE');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='PO_UPDATED' AND ScopeCode='FINANCE_SHARED') INSERT cfg.SourceScope VALUES('PO_UPDATED','FINANCE_SHARED');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='AP_REPORT' AND OwnerRoleCode<>'FINANCE') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='AP_REPORT') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('AP_REPORT',N'AP_REPORT','FINANCE');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='AP_REPORT' AND ScopeCode='FINANCE_SHARED') INSERT cfg.SourceScope VALUES('AP_REPORT','FINANCE_SHARED');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='SUPPLIER_PAYMENT_REGISTER' AND OwnerRoleCode<>'FINANCE') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='SUPPLIER_PAYMENT_REGISTER') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('SUPPLIER_PAYMENT_REGISTER',N'SUPPLIER_PAYMENT_REGISTER','FINANCE');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='SUPPLIER_PAYMENT_REGISTER' AND ScopeCode='FINANCE_SHARED') INSERT cfg.SourceScope VALUES('SUPPLIER_PAYMENT_REGISTER','FINANCE_SHARED');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='EX_VND' AND OwnerRoleCode<>'FINANCE') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='EX_VND') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('EX_VND',N'EX_VND','FINANCE');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='EX_VND' AND ScopeCode='FINANCE_SHARED') INSERT cfg.SourceScope VALUES('EX_VND','FINANCE_SHARED');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='EX_USD' AND OwnerRoleCode<>'FINANCE') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='EX_USD') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('EX_USD',N'EX_USD','FINANCE');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='EX_USD' AND ScopeCode='FINANCE_SHARED') INSERT cfg.SourceScope VALUES('EX_USD','FINANCE_SHARED');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='LOGISTICS_1000' AND OwnerRoleCode<>'LOGISTICS') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='LOGISTICS_1000') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('LOGISTICS_1000',N'LOGISTICS_1000','LOGISTICS');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='LOGISTICS_1000' AND ScopeCode='SITE_1000') INSERT cfg.SourceScope VALUES('LOGISTICS_1000','SITE_1000');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='PIN_TEST_1000' AND OwnerRoleCode<>'LOGISTICS') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='PIN_TEST_1000') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('PIN_TEST_1000',N'PIN_TEST_1000','LOGISTICS');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='PIN_TEST_1000' AND ScopeCode='SITE_1000') INSERT cfg.SourceScope VALUES('PIN_TEST_1000','SITE_1000');
IF EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='LOGISTICS_6000' AND OwnerRoleCode<>'LOGISTICS') THROW 51000,'Existing source ownership differs; review before installing.',1;
IF NOT EXISTS(SELECT 1 FROM cfg.SourceType WHERE SourceCode='LOGISTICS_6000') INSERT cfg.SourceType(SourceCode,SourceName,OwnerRoleCode) VALUES('LOGISTICS_6000',N'LOGISTICS_6000','LOGISTICS');
IF NOT EXISTS(SELECT 1 FROM cfg.SourceScope WHERE SourceCode='LOGISTICS_6000' AND ScopeCode='SITE_6000') INSERT cfg.SourceScope VALUES('LOGISTICS_6000','SITE_6000');
COMMIT;
